        assert(isfile('rays.shd'),'Missing BELLHOP SHD');
        write_field_result('rays.shd',cfg,water_depth,'bellhop',run_type,output);return
    end
    assert(isfile('rays.ray') && isfile('rays.prt'),'Missing BELLHOP output');
