"""Read this AT build's RAM sequential-unformatted TL grid, checking each record.

The grid contains TL, not complex pressure: phase cannot be reconstructed.
For this executable, sample i=ndz has physical depth (ndz-1)*dz.
The local AT MATLAB reader labels these one dz deeper; a zr=1 m probe
independently confirms the offset for this build. Other RAM builds need a probe.
"""
import argparse,json,struct
from pathlib import Path
import numpy as np

def read_grid(path):
    with Path(path).open('rb') as f:
        marker=f.read(4)
        if len(marker)!=4:raise ValueError('Missing RAM header')
        endian=next((e for e in ('<','>') if struct.unpack(e+'i',marker)[0]==60),None)
        if endian is None:raise ValueError('Unsupported RAM header: expected 4-byte markers and 60-byte payload')
        header=f.read(60);tail=f.read(4)
        if len(header)!=60 or len(tail)!=4 or struct.unpack(endian+'i',tail)[0]!=60:raise ValueError('Truncated RAM header or mismatched marker')
        names=['frequency_hz','source_depth_m','receiver_depth_m','range_max_m','dr_m','ndr','zmax_m','dz_m','ndz','zmplt_m','c0_m_s','pade_terms','stability_terms','stability_range_m','depth_count']
        meta=dict(zip(names,struct.unpack(endian+'5fi2fi2f2ifi',header)))
        nz=meta['depth_count'];step=meta['dr_m']*meta['ndr'];dz=meta['dz_m']*meta['ndz']
        if not np.isfinite(list(meta.values())).all() or not 0<nz<=100000 or min(step,dz)<=0 or meta['range_max_m']<=0:raise ValueError('Invalid RAM grid dimensions')
        columns=[]
        while True:
            begin=f.read(4)
            if not begin:break
            if len(begin)!=4 or struct.unpack(endian+'i',begin)[0]!=nz*4:raise ValueError('RAM range record marker mismatch')
            payload=f.read(nz*4);end=f.read(4)
            if len(payload)!=nz*4 or len(end)!=4 or struct.unpack(endian+'i',end)[0]!=nz*4:raise ValueError('Truncated RAM range record')
            columns.append(np.frombuffer(payload,dtype=endian+'f4').astype(float))
            if len(columns)*nz>50000000:raise ValueError('RAM grid too large for this reader')
        expected=int(np.floor(meta['range_max_m']/step+1e-5))
        if not columns or len(columns)!=expected:raise ValueError(f'RAM range count mismatch: {len(columns)} != {expected}')
    return {'metadata':meta,'ranges_m':np.arange(1,len(columns)+1)*step,'depths_m':np.arange(1,nz+1)*dz-meta['dz_m'],'at_matlab_nominal_depths_m':np.arange(1,nz+1)*dz,'tl_db':np.stack(columns,axis=1)}

def export(path,output):
    data=read_grid(path);out=Path(output);out.mkdir(parents=True,exist_ok=True)
    tl=data['tl_db'];finite=np.isfinite(tl)
    if not finite.any():raise ValueError('RAM output has no finite TL')
    summary={**data['metadata'],'shape':list(tl.shape),'finite_ratio':float(finite.mean()),'first_depth_m':float(data['depths_m'][0]),'first_range_m':float(data['ranges_m'][0]),'tl_min_db':float(np.min(tl[finite])),'tl_max_db':float(np.max(tl[finite])),'depth_convention':'Physical depth (sample_index*ndz-1)*dz; differs by -dz from local MATLAB reader; verified for current executable by receiver-depth probe.','note':'TL output only; no phase, not a complex-pressure SHD reconstruction.'}
    line=Path(path).with_name('tl.line')
    if line.exists():
        curve=np.loadtxt(line,ndmin=2);z=data['metadata']['receiver_depth_m'];k=int(np.argmin(abs(data['depths_m']-z)))
        if len(curve)==len(data['ranges_m']) and np.allclose(curve[:,0],data['ranges_m'],atol=.01) and abs(data['depths_m'][k]-z)<1e-4:
            valid=np.isfinite(curve[:,1])&np.isfinite(tl[k]);summary['line_grid_max_abs_db']=float(np.max(abs(curve[valid,1]-tl[k,valid]))) if valid.any() else None
            summary['line_grid_compared_points']=int(valid.sum())
    np.savez_compressed(out/'ram_grid.npz',ranges_m=data['ranges_m'],depths_m=data['depths_m'],tl_db=tl)
    (out/'ram_summary.json').write_text(json.dumps(summary,indent=2,allow_nan=False),encoding='utf-8')
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(9,5));vmin,vmax=np.percentile(tl[finite],[2,98]);img=ax.pcolormesh(data['ranges_m']/1000,data['depths_m'],tl,shading='auto',cmap='viridis_r',vmin=vmin,vmax=vmax);ax.invert_yaxis();ax.set(xlabel='Range (km)',ylabel='Depth (m)',title='RAM transmission loss (display limits: P2-P98)');fig.colorbar(img,ax=ax,label='TL (dB)');fig.tight_layout();fig.savefig(out/'ram_tl.png',dpi=150);plt.close(fig)
    return summary

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('grid');parser.add_argument('--out-dir',required=True);args=parser.parse_args();print(json.dumps(export(args.grid,args.out_dir),ensure_ascii=False))

% Shared structural checks. This is not a physical accuracy certificate.
assert(isfile(workflow_output),'Expected fresh model output missing');
[PlotTitle,PlotType,freqVec,atten,Pos,pressure]=read_shd(workflow_output);
assert(any(isfinite(pressure(:)) & abs(pressure(:))>0),'No finite nonzero field');
nz=size(pressure,3); nr=size(pressure,4);
assert(numel(Pos.r.depth)==nz && numel(Pos.r.range)==nr,'Coordinate dimensions disagree');
slice=reshape(pressure(1,1,:,:),nz,nr);
level=-20*log10(abs(slice)); level(~isfinite(level))=NaN;
assert(any(isfinite(level(:))),'Selected slice has no finite field');
relative=strcmp(workflow_axis,'time_s');
if relative, label='Relative amplitude level (dB; source normalization required)'; else, label='TL (dB; AT source convention)'; end
save('model_pressure.mat','PlotTitle','PlotType','freqVec','atten','Pos','pressure','workflow_axis','-v7');
[R,Z]=meshgrid(Pos.r.range,Pos.r.depth);
writematrix([R(:),Z(:),level(:)],'field_slice.csv');
figure('Visible','off'); imagesc(Pos.r.range/1000,Pos.r.depth,level); set(gca,'YDir','reverse'); colorbar;
xlabel('Range (km)'); ylabel('Receiver depth (m)'); title([workflow_model ' | ' label],'Interpreter','none');
exportgraphics(gcf,'field_slice.png','Resolution',150); close all;
metrics=struct('model',workflow_model,'output',workflow_output,'frequency_or_carrier_hz',freqVec,'pressure_shape',size(pressure),'finite_ratio',sum(isfinite(pressure(:)))/numel(pressure),'selected_bearing_index',1,'selected_source_or_time_index',1,'source_axis',workflow_axis,'level_label',label,'csv_columns',{{'range_m','receiver_depth_m','level_db'}},'scope','Execution and output structure checked; convergence and physical accuracy need separate evidence');
if relative, metrics.selected_time_s=Pos.s.depth(1); else, metrics.selected_source_depth_m=Pos.s.depth(1); end
fid=fopen('model_metrics.json','w'); assert(fid>=0); fwrite(fid,jsonencode(metrics)); fclose(fid);
disp('MODEL_WORKFLOW_OUTPUT_CHECKED');

@workbench/skills/seasonal-layer-diagnos.content:
"""Reproducible climatological layer diagnostics, independent of an LLM/provider."""
import argparse,csv,json,sys
from pathlib import Path
import numpy as np
import gsw

def crossing(depth,departure,threshold):
    hits=np.flatnonzero(departure>=threshold)
    if not len(hits):return {'depth_m':None,'status':'not_crossed','observed_to_m':float(depth[-1])}
    i=int(hits[0])
    value=depth[i] if i==0 else depth[i-1]+(depth[i]-depth[i-1])*(threshold-departure[i-1])/(departure[i]-departure[i-1])
    return {'depth_m':float(value),'status':'crossed'}

def diagnose(profile,reference=10.,density_threshold=.03,temperature_threshold=.2):
    if reference<0 or density_threshold<=0 or temperature_threshold<=0:raise ValueError('Invalid diagnostic thresholds')
    rows=profile['rows'];z=np.array([r['depth_m'] for r in rows],dtype=float)
    if len(z)<2 or not np.isfinite(z).all() or np.any(np.diff(z)<=0):raise ValueError('Depth must be finite and strictly increasing')
    missing=[d for d in profile.get('missing_depths_m',[]) if z[0]<=d<=z[-1]]
    if missing:
        cutoff=min(missing);rows=[r for r in rows if r['depth_m']<cutoff];z=np.array([r['depth_m'] for r in rows],dtype=float)
    result={'requested':profile.get('requested'),'selected':profile.get('selected'),'period_id':profile.get('period_id'),'period':profile.get('period'),'reference_depth_m':reference,'density_threshold_kg_m3':density_threshold,'temperature_threshold_c':temperature_threshold,'internal_missing_cutoff_m':min(missing) if missing else None}
    if len(z)<2 or z[0]>reference or z[-1]<=reference:
        return {**result,'density_mld':{'depth_m':None,'status':'insufficient_reference'},'temperature_mld':{'depth_m':None,'status':'insufficient_reference'},'surface_duct':{'depth_m':None,'status':'insufficient_profile'}}
    temperature=np.array([r['temperature_c'] for r in rows]);sal=np.array([r['practical_salinity'] for r in rows]);sound=np.array([r['sound_speed_m_s'] for r in rows]);pos=profile['selected']
    if not np.isfinite([temperature,sal,sound]).all():raise ValueError('Profile contains nonfinite values')
    pressure=gsw.p_from_z(-z,pos['lat']);sa=gsw.SA_from_SP(sal,pressure,pos['lon'],pos['lat']);ct=gsw.CT_from_t(sa,temperature,pressure);sigma=gsw.sigma0(sa,ct);pt=gsw.pt0_from_t(sa,temperature,pressure)
    ref_sigma=float(np.interp(reference,z,sigma));ref_pt=float(np.interp(reference,z,pt));zz=np.r_[reference,z[z>reference]];dd=np.r_[0,sigma[z>reference]-ref_sigma];dt=np.r_[0,np.abs(pt[z>reference]-ref_pt)]
    result.update(density_mld=crossing(zz,dd,density_threshold),temperature_mld=crossing(zz,dt,temperature_threshold))
    slope=np.diff(sound)/np.diff(z)
    if z[0]!=0:duct={'depth_m':None,'status':'missing_surface'}
    elif slope[0]<=1e-6:duct={'depth_m':None,'status':'no_surface_connected_positive_gradient'}
    else:
        stop=np.flatnonzero(slope<=1e-6)
        duct={'depth_m':float(z[int(stop[0])]),'status':'candidate_local_maximum','sound_speed_increase_m_s':float(sound[int(stop[0])]-sound[0])} if len(stop) else {'depth_m':None,'status':'positive_gradient_unclosed','observed_to_m':float(z[-1])}
    result['surface_duct']=duct;result['note']='Climatological threshold diagnostics; candidate sound-speed duct is not proof of acoustic trapping.'
    return result

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--profiles');parser.add_argument('--lon',type=float);parser.add_argument('--lat',type=float);parser.add_argument('--periods',default='13,14,15,16');parser.add_argument('--out-dir',required=True);args=parser.parse_args()
    if args.profiles:profiles=json.loads(Path(args.profiles).read_text(encoding='utf-8-sig'))
    else:
        if args.lon is None or args.lat is None:parser.error('Use --profiles or both --lon and --lat')
        sys.path.insert(0,str(Path(__file__).resolve().parents[3]/'backend'));import ocean_data
        profiles=[ocean_data.profile(args.lon,args.lat,int(p)) for p in args.periods.split(',')]
    if not profiles:raise ValueError('No profiles')
    results=[diagnose(p) for p in profiles];out=Path(args.out_dir);out.mkdir(parents=True,exist_ok=True)
    (out/'profiles.json').write_text(json.dumps(profiles,ensure_ascii=False,indent=2,allow_nan=False),encoding='utf-8')
    (out/'layer_metrics.json').write_text(json.dumps(results,ensure_ascii=False,indent=2,allow_nan=False),encoding='utf-8')
    with (out/'layer_metrics.csv').open('w',encoding='utf-8-sig',newline='') as f:
        w=csv.writer(f);w.writerow(['lon','lat','period','density_mld_m','density_status','temperature_mld_m','temperature_status','duct_candidate_m','duct_status'])
        for r in results:w.writerow([r['selected']['lon'],r['selected']['lat'],r['period_id'],r['density_mld']['depth_m'],r['density_mld']['status'],r['temperature_mld']['depth_m'],r['temperature_mld']['status'],r['surface_duct']['depth_m'],r['surface_duct']['status']])
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    labels=[str(r['period_id']) for r in results];fig,ax=plt.subplots(figsize=(8,4))
    for key,label in [('density_mld','Density MLD'),('temperature_mld','Temperature MLD'),('surface_duct','Duct candidate')]:
        ax.plot(range(len(results)),[r[key]['depth_m'] if r[key]['depth_m'] is not None else np.nan for r in results],marker='o',label=label)
    ax.set(xticks=range(len(labels)),xticklabels=labels,xlabel='WOA period (13-16: seasons)',ylabel='Depth (m)',title='Climatological layer diagnostics');ax.invert_yaxis();ax.legend();fig.tight_layout();fig.savefig(out/'seasonal_layers.png',dpi=150);plt.close(fig)
    fig,axes=plt.subplots(1,3,figsize=(12,5),sharey=True)
    for p in profiles:
        for ax,key in zip(axes,['temperature_c','practical_salinity','sound_speed_m_s']):ax.plot([r[key] for r in p['rows']],[r['depth_m'] for r in p['rows']],label=str(p['period_id']))
    for ax,title in zip(axes,['Temperature (C)','Practical salinity','Sound speed (m/s)']):ax.set(xlabel=title,ylim=(min(300,max(p['rows'][-1]['depth_m'] for p in profiles)),0));ax.grid(alpha=.2)
    axes[0].set_ylabel('Depth (m)');axes[-1].legend(title='WOA period');fig.tight_layout();fig.savefig(out/'seasonal_profiles.png',dpi=150);plt.close(fig)
    print(json.dumps({'out_dir':str(out),'profiles':len(results),'metrics':results},ensure_ascii=False))

if __name__=='__main__':main()

