[~, f, ~, ~, P] = read_env('case.env','KRAKEN');
assert(abs(f-cfg.frequency_hz)<1e-6 && abs(P.s.depth(1)-cfg.source_depth_m)<1e-4,'ENV roundtrip mismatch');
